import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        # Retry for 429: up to 3 retries (initial + 3 retries = 4 attempts total)
        # Backoff: 0.5s, 1s, 2s
        for attempt in range(4):  # attempt 0 is initial, 1-3 are retries
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                body = response.read().decode('utf-8')
                status_code = response.getcode()

                if status_code == 429:
                    if attempt < 3:
                        # Exponential backoff: 0.5, 1, 2 seconds
                        backoff = 0.5 * (2 ** attempt)
                        time.sleep(backoff)
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after 3 retries")

                elif 500 <= status_code < 600:
                    # Server error: retry once after 1s
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {status_code}")

                elif 400 <= status_code < 500:
                    if status_code == 429:
                        # Already handled above, but just in case
                        raise RateLimitError(f"Rate limit exceeded")
                    else:
                        raise ClientError(f"Client error {status_code}")

                else:
                    # Success
                    return body

            except urllib.error.HTTPError as e:
                status_code = e.code

                if status_code == 429:
                    if attempt < 3:
                        backoff = 0.5 * (2 ** attempt)
                        time.sleep(backoff)
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after 3 retries")

                elif 500 <= status_code < 600:
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {status_code}")

                elif 400 <= status_code < 500:
                    if status_code == 429:
                        raise RateLimitError(f"Rate limit exceeded")
                    else:
                        raise ClientError(f"Client error {status_code}")

                else:
                    raise ClientError(f"Client error {status_code}")

            except urllib.error.URLError:
                # Network error: retry once after 1s
                if attempt == 0:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError("Connection error after retry")
